function mostBackToBackCopies(text: string, word: string): number {
  const n = text.length, m = word.length;
  const run = new Array<number>(n + 1).fill(0); // copies ending exactly at i
  let best = 0;
  for (let i = m; i <= n; i++) {
    if (text.slice(i - m, i) === word) {
      run[i] = run[i - m] + 1;
      best = Math.max(best, run[i]);
    }
  }
  return best;
}

