class Solution:
    def mostBackToBackCopies(self, text: str, word: str) -> int:
        n, m = len(text), len(word)
        run = [0] * (n + 1)
        for i in range(m, n + 1):
            if text[i - m:i] == word:
                run[i] = run[i - m] + 1
        return max(run)

